const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch({ headless: true });
  const page = await browser.newPage();
  const htmlPath = path.resolve('/app/output/poster.html');
  await page.goto('file://' + htmlPath, { waitUntil: 'networkidle' });
  // Wait for fonts and infographic to render
  await page.waitForTimeout(3000);
  // Ensure the infographic container has content
  await page.waitForSelector('#lang-chart svg', { timeout: 10000 }).catch(() => {});
  await page.waitForTimeout(2000);

  // Screenshot the poster element
  const poster = await page.$('#poster');
  await poster.screenshot({
    path: '/app/output/final_poster.png',
    type: 'png',
  });

  await browser.close();
  console.log('Poster saved to /app/output/final_poster.png');
})();
